package com.quincaisoft.platformcontrol.application;
import com.quincaisoft.platformcontrol.api.PlatformGovernanceService;
import com.quincaisoft.platformcontrol.infrastructure.*;import com.quincaisoft.shared.*;
import jakarta.persistence.*;import org.springframework.stereotype.Service;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.security.access.AccessDeniedException;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;
import tools.jackson.databind.json.JsonMapper;import java.util.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.function.Supplier;

@Service public class DefaultPlatformGovernanceService implements PlatformGovernanceService{
 private final EntityManager em;private final TransactionTemplate platformTx;private final ScopedTransactions merchantTx;private final JsonMapper json;
 public DefaultPlatformGovernanceService(EntityManager em,PlatformTransactionManager manager,ScopedTransactions merchantTx,JsonMapper json){this.em=em;this.platformTx=new TransactionTemplate(manager);this.merchantTx=merchantTx;this.json=json;}
 private UUID actor(String scope){var a=SecurityContextHolder.getContext().getAuthentication();if(!(a instanceof JwtAuthenticationToken jwt)||!a.isAuthenticated()||a.getAuthorities().stream().noneMatch(x->x.getAuthority().equals(scope)||x.getAuthority().equals("SCOPE_"+scope)))throw new AccessDeniedException("Required governance capability missing");try{return UUID.fromString(jwt.getToken().getSubject());}catch(RuntimeException e){throw new AccessDeniedException("Authenticated identity required");}}
 private <T>T platform(String scope,Supplier<T> work){UUID actor=actor(scope);return platformTx.execute(st->{set("app.platform_actor",actor.toString());set("app.actor_id",actor.toString());Number n=(Number)em.createNativeQuery("select count(*) from platform_operator where actor_id=:a and active").setParameter("a",actor).getSingleResult();if(n.longValue()!=1)throw new AccessDeniedException("Active enrolled platform operator required");return work.get();});}
 private <T>T owner(String scope,Supplier<T> work){UUID authenticated=actor(scope);return merchantTx.execute(()->{var s=TenantContext.current();if(!authenticated.equals(s.actorId()))throw new AccessDeniedException("Authenticated owner must match tenant scope");Number n=(Number)em.createNativeQuery("select count(*) from tenant_memberships where tenant_id=:t and company_id=:c and branch_id=:b and actor_id=:a and active and role_code='owner' and authorization_epoch=:e").setParameter("t",s.tenantId()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("a",s.actorId()).setParameter("e",TenantContext.authorizationEpoch()).getSingleResult();if(n.longValue()!=1)throw new AccessDeniedException("Current scoped tenant owner consent required");return work.get();});}
 public List<Grant> merchantGrants(){return owner("support:read",()->em.createQuery("select g from SupportGrant g order by g.createdAt desc,g.id",SupportGrant.class).setMaxResults(100).getResultList().stream().map(this::grantView).toList());}
 public Grant consent(Consent input){if(input==null||input.operationId()==null||input.operatorId()==null||input.expiresAt()==null)throw new IllegalArgumentException("Operation, operator and expiry required");text(input.ticketReference(),1,200);text(input.reason(),3,2000);
  return owner("support:write",()->{var s=TenantContext.current();return once(s.tenantId(),input.operationId(),s.actorId(),"SUPPORT_CONSENT",input,Grant.class,()->{
   if(input.operatorId().equals(s.actorId())||!input.expiresAt().isAfter(now())||input.expiresAt().isAfter(now().plus(24,ChronoUnit.HOURS)))throw new IllegalArgumentException("Named separate support operator and expiry within 24 hours required");
   var g=new SupportGrant();g.id=UUID.randomUUID();g.tenantId=s.tenantId();g.companyId=s.companyId();g.branchId=s.branchId();g.ownerActorId=s.actorId();g.operatorId=input.operatorId();g.ticketReference=input.ticketReference();g.reason=input.reason();g.status="PENDING";g.createdAt=now();g.expiresAt=input.expiresAt().truncatedTo(ChronoUnit.MICROS);em.persist(g);em.flush();event(g.tenantId,s.actorId(),input.operationId(),g.id,"SupportConsented");return grantView(g);
  });});}
 public Grant revoke(UUID id,Command input){command(input);return owner("support:write",()->{var s=TenantContext.current();return once(s.tenantId(),input.operationId(),s.actorId(),"SUPPORT_REVOKE",List.of(id,input),Grant.class,()->{
  var g=grant(id);if(!g.tenantId.equals(s.tenantId())||!g.companyId.equals(s.companyId())||!g.branchId.equals(s.branchId()))throw new NoSuchElementException("Support grant not found");if(g.version!=input.expectedVersion()||g.status.equals("REVOKED"))throw new IllegalStateException("Current revocable grant required");g.status="REVOKED";g.revokedBy=s.actorId();em.flush();event(g.tenantId,s.actorId(),input.operationId(),g.id,"SupportRevoked");return grantView(g);
 });});}
 public List<Grant> platformGrants(){return platform("platform:support:read",()->em.createQuery("select g from SupportGrant g order by g.createdAt desc,g.id",SupportGrant.class).setMaxResults(100).getResultList().stream().map(this::grantView).toList());}
 public Grant approveGrant(UUID id,Command input){command(input);return platform("platform:support:approve",()->{var g=grant(id);UUID actor=actor("platform:support:approve");return once(g.tenantId,input.operationId(),actor,"SUPPORT_APPROVE",List.of(id,input),Grant.class,()->{
  if(g.version!=input.expectedVersion()||!g.status.equals("PENDING")||!g.expiresAt.isAfter(now()))throw new IllegalStateException("Current unexpired pending grant required");if(actor.equals(g.operatorId)||actor.equals(g.ownerActorId))throw new AccessDeniedException("Separate platform approver required");g.approvedBy=actor;g.status="ACTIVE";em.flush();event(g.tenantId,actor,input.operationId(),g.id,"SupportApproved");return grantView(g);
 });});}
 public Diagnostics diagnostics(UUID id,UUID correlation){if(correlation==null)throw new IllegalArgumentException("Correlation required");return platform("platform:support:read",()->{
  var g=grant(id);UUID operator=actor("platform:support:read");if(!g.operatorId.equals(operator)||!g.status.equals("ACTIVE")||!g.expiresAt.isAfter(now()))throw new AccessDeniedException("Current consented named-operator support grant required");
  set("app.tenant_id",g.tenantId.toString());set("app.company_id",g.companyId.toString());set("app.branch_id",g.branchId.toString());
  // The operator remains the actor. No owner token/membership or impersonation is fabricated.
  var result=new Diagnostics(g.id,g.tenantId,g.companyId,g.branchId,now(),count("select count(*) from catalog_product"),count("select count(*) from sale where status in('POSTED','PARTIALLY_RETURNED','FULLY_RETURNED')"),count("select count(*) from stock_balance"));
  event(g.tenantId,operator,correlation,g.id,"SupportDiagnosticsRead");return result;
 });}
 public TenantLifecyclePolicy.State tenantState(UUID tenant){return platform("platform:governance:read",()->{requireTenant(tenant);return state(tenant);});}
 public List<Hold> holds(UUID tenant){return platform("platform:governance:read",()->{requireTenant(tenant);return em.createQuery("select h from TenantLegalHold h where h.tenantId=:t order by h.createdAt desc,h.id",TenantLegalHold.class).setParameter("t",tenant).setMaxResults(100).getResultList().stream().map(this::holdView).toList();});}
 public List<Review> requests(UUID tenant){return platform("platform:governance:read",()->{requireTenant(tenant);return em.createQuery("select r from GovernanceRequest r where r.tenantId=:t order by r.createdAt desc,r.id",GovernanceRequest.class).setParameter("t",tenant).setMaxResults(100).getResultList().stream().map(this::reviewView).toList();});}
 public Review request(UUID tenant,Request input){if(input==null||input.operationId()==null||input.kind()==null||input.expectedVersion()<0)throw new IllegalArgumentException("Operation, kind and version required");text(input.reference(),1,200);text(input.reason(),3,2000);if((input.kind()==Kind.RELEASE_LEGAL_HOLD)!=(input.holdId()!=null))throw new IllegalArgumentException("Hold identity required only for release");
  return platform("platform:governance:write",()->{requireTenant(tenant);UUID actor=actor("platform:governance:write");return once(tenant,input.operationId(),actor,"GOVERNANCE_REQUEST",input,Review.class,()->{
   target(tenant,input.kind(),input.expectedVersion(),input.holdId());var r=new GovernanceRequest();r.id=UUID.randomUUID();r.tenantId=tenant;r.kind=input.kind().name();r.status="PENDING";r.requestedBy=actor;r.expectedTargetVersion=input.expectedVersion();r.reference=input.reference();r.reason=input.reason();r.holdId=input.holdId();r.createdAt=now();em.persist(r);em.flush();event(tenant,actor,input.operationId(),r.id,"GovernanceRequested");return reviewView(r);
  });});}
 public Review approve(UUID id,Command input){command(input);return platform("platform:governance:approve",()->{
  var r=em.find(GovernanceRequest.class,id,LockModeType.PESSIMISTIC_WRITE);if(r==null)throw new NoSuchElementException("Governance request not found");UUID actor=actor("platform:governance:approve");return once(r.tenantId,input.operationId(),actor,"GOVERNANCE_APPROVE",List.of(id,input),Review.class,()->{
   if(r.version!=input.expectedVersion()||!r.status.equals("PENDING"))throw new IllegalStateException("Current pending review required");if(actor.equals(r.requestedBy))throw new AccessDeniedException("Separate platform approver required");
   Kind kind=Kind.valueOf(r.kind);lockTenant(r.tenantId);target(r.tenantId,kind,r.expectedTargetVersion,r.holdId);r.approvedBy=actor;r.status="APPLIED";em.flush();
   switch(kind){
    case SUSPEND,RESUME -> {var state=em.find(TenantLifecycle.class,r.tenantId);boolean fresh=state==null;if(fresh){state=new TenantLifecycle();state.tenantId=r.tenantId;}state.status=kind==Kind.SUSPEND?"SUSPENDED":"ACTIVE";state.epoch=Math.incrementExact(r.expectedTargetVersion);state.lastDecisionId=r.id;if(fresh)em.persist(state);em.flush();event(r.tenantId,actor,input.operationId(),r.id,kind==Kind.SUSPEND?"TenantSuspended":"TenantResumed");}
    case PLACE_LEGAL_HOLD -> {var h=new TenantLegalHold();h.id=r.id;h.tenantId=r.tenantId;h.reference=r.reference;h.reason=r.reason;h.status="ACTIVE";h.placedBy=actor;h.createdAt=now();em.persist(h);em.flush();event(r.tenantId,actor,input.operationId(),h.id,"LegalHoldPlaced");}
    case RELEASE_LEGAL_HOLD -> {var h=em.find(TenantLegalHold.class,r.holdId,LockModeType.PESSIMISTIC_WRITE);set("app.hold_release_request",r.id.toString());h.status="RELEASED";h.releasedBy=actor;em.flush();event(r.tenantId,actor,input.operationId(),h.id,"LegalHoldReleased");}
   }return reviewView(r);
  });
 });}
 private void target(UUID tenant,Kind kind,long expected,UUID hold){if(kind==Kind.SUSPEND||kind==Kind.RESUME){var s=state(tenant);if(s.epoch()!=expected||kind==Kind.SUSPEND&&!s.status().equals("ACTIVE")||kind==Kind.RESUME&&!s.status().equals("SUSPENDED"))throw new IllegalStateException("Current lifecycle version and transition required");}
  else if(kind==Kind.PLACE_LEGAL_HOLD){if(expected!=0)throw new IllegalArgumentException("New legal hold version must be zero");}
  else{var h=em.find(TenantLegalHold.class,hold,LockModeType.PESSIMISTIC_WRITE);if(h==null||!h.tenantId.equals(tenant))throw new NoSuchElementException("Legal hold not found");if(h.version!=expected||!h.status.equals("ACTIVE"))throw new IllegalStateException("Current active legal hold required");}}
 private TenantLifecyclePolicy.State state(UUID tenant){var r=em.find(TenantLifecycle.class,tenant);return r==null?new TenantLifecyclePolicy.State(tenant,"ACTIVE",0,null):new TenantLifecyclePolicy.State(tenant,r.status,r.epoch,r.lastDecisionId);}
 private void requireTenant(UUID id){if(id==null)throw new IllegalArgumentException("Tenant required");set("app.tenant_id",id.toString());Number n=(Number)em.createNativeQuery("select count(*) from tenant where id=:t").setParameter("t",id).getSingleResult();if(n.longValue()!=1)throw new NoSuchElementException("Tenant not found");}
 private void lockTenant(UUID tenant){em.createNativeQuery("select 1 from pg_advisory_xact_lock(hashtextextended(:k,0))").setParameter("k","tenant-lifecycle:"+tenant).getSingleResult();}
 private SupportGrant grant(UUID id){var g=em.find(SupportGrant.class,Objects.requireNonNull(id),LockModeType.PESSIMISTIC_WRITE);if(g==null)throw new NoSuchElementException("Support grant not found");return g;}
 private <T>T once(UUID tenant,UUID operation,UUID actor,String kind,Object input,Class<T> type,Supplier<T> work){String hash=sha(json.writeValueAsString(List.of(tenant,actor,kind,input)));em.createNativeQuery("select 1 from pg_advisory_xact_lock(hashtextextended(:k,0))").setParameter("k","governance-operation:"+tenant+":"+operation).getSingleResult();var old=em.find(GovernanceOperation.class,new GovernanceOperation.Key(tenant,operation));if(old!=null){if(!old.actorId.equals(actor)||!old.requestHash.equals(hash))throw new IllegalStateException("Governance operation reused");return json.readValue(old.responseText,type);}T result=work.get();var op=new GovernanceOperation();op.id=operation;op.tenantId=tenant;op.actorId=actor;op.requestHash=hash;op.responseText=json.writeValueAsString(result);op.createdAt=now();em.persist(op);em.flush();return result;}
 private void event(UUID tenant,UUID actor,UUID correlation,UUID source,String kind){var e=new GovernanceEvent();e.id=UUID.randomUUID();e.tenantId=tenant;e.actorId=actor;e.correlationId=correlation;e.sourceId=source;e.eventType=kind;e.createdAt=now();em.persist(e);em.flush();}
 private Grant grantView(SupportGrant g){return new Grant(g.id,g.tenantId,g.companyId,g.branchId,g.ownerActorId,g.operatorId,g.approvedBy,g.status,g.expiresAt,Long.toString(g.version),g.ticketReference,g.reason);}
 private Review reviewView(GovernanceRequest r){return new Review(r.id,r.tenantId,Kind.valueOf(r.kind),r.status,r.requestedBy,r.approvedBy,r.expectedTargetVersion,Long.toString(r.version),r.reference,r.reason,r.holdId);}
 private Hold holdView(TenantLegalHold h){return new Hold(h.id,h.tenantId,h.reference,h.reason,h.status,h.placedBy,h.releasedBy,Long.toString(h.version));}
 private String count(String query){return ((Number)em.createNativeQuery(query).getSingleResult()).toString();}
 private void set(String key,String value){em.createNativeQuery("select set_config(:k,:v,true)").setParameter("k",key).setParameter("v",value).getSingleResult();}
 private static void command(Command i){if(i==null||i.operationId()==null||i.expectedVersion()<0)throw new IllegalArgumentException("Operation/version required");text(i.reason(),3,2000);}
 private static void text(String s,int min,int max){if(s==null||s.trim().length()<min||s.length()>max||s.chars().anyMatch(Character::isISOControl))throw new IllegalArgumentException("Bounded reference/reason required");}
 private static Instant now(){return Instant.now().truncatedTo(ChronoUnit.MICROS);}
 private static String sha(String s){try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(s.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
